import sys

def is_palindrome_opt(s: str) -> bool:
    l, r = 0, len(s) - 1
    while l < r:
        while l < r and not s[l].isalnum():
            l += 1
        while l < r and not s[r].isalnum():
            r -= 1
        if l < r and s[l].lower() != s[r].lower():
            return False
        l += 1
        r -= 1
    return True

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip('\n')
    print('true' if is_palindrome_opt(s) else 'false')

import sys

def _alnum_lower(ch: str) -> bool:
    o = ord(ch)
    if (ord('0') <= o <= ord('9') or
        ord('a') <= o <= ord('z') or
        ord('A') <= o <= ord('Z')):
        return ch.lower() if ord('A') <= o <= ord('Z') else ch
    return ''

def is_palindrome_best(s: str) -> bool:
    l, r = 0, len(s) - 1
    while l < r:
        cl = _alnum_lower(s[l])
        cr = _alnum_lower(s[r])
        if cl and cr:
            if cl != cr:
                return False
            l += 1
            r -= 1
        else:
            if not cl:
                l += 1
            if not cr:
                r -= 1
    return True

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip('\n')
    print('true' if is_palindrome_best(s) else 'false')
